describe('Currency Field Formatting', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should format currency input with commas and two decimal places', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-form').as('formSubmit');

    // Locate the currency input field
    cy.get('[data-testid="currency-input"]').should('be.visible');

    // Type a number without formatting
    cy.get('[data-testid="currency-input"]').type('1234967');

    // Verify the input field displays formatted value
    cy.get('[data-testid="currency-input"]').should('have.value', '1,234,967.00');

    // Type another number with decimals
    cy.get('[data-testid="currency-input"]').clear().type('1234967.5');

    // Verify the input field displays formatted value with two decimal places
    cy.get('[data-testid="currency-input"]').should('have.value', '1,238,500.50');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API call
    cy.wait('@formSubmit');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should handle negative numbers and empty input gracefully', () => {
    // Intercept the form submission API
    cy.intercept('POST', '/api/submit-form').as('formSubmit');

    // Locate the currency input field
    cy.get('[data-testid="currency-input"]').should('be.visible');

    // Type a negative number
    cy.get('[data-testid="currency-input"]').type('-12345.6');

    // Verify negative number is formatted correctly
    cy.get('[data-testid="currency-input"]').should('have.value', '-12,345.60');

    // Clear the input field
    cy.get('[data-testid="currency-input"]').clear();

    // Verify input is empty
    cy.get('[data-testid="currency-input"]').should('have.value', '');

    // Attempt to submit with empty field
    cy.get('[data-testid="submit-button"]').click();

    // Verify validation error appears
    cy.get('[data-testid="validation-error"]').should('be.visible');
    cy.get('[data-testid="validation-error"]').should('contain', 'Currency field is required');

    // Verify form was not submitted
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Type a valid value and submit
    cy.get('[data-testid="currency-input"]').type('100.00');
    cy.get('[data-testid="submit-button"]').click();

    // Wait for API call
    cy.wait('@formSubmit');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
  });
});
